// Run the CLI and resolve to a process exit code. Kept separate from the bin
// shim so tests can call run() directly with injected deps and assert on the
// captured output and exit code without spawning a subprocess.
import { CommanderError } from "commander";
import { buildProgram, defaultDeps } from "./program.js";
import { OutputError, logOf } from "./io.js";
import { DEFAULT_LOG_FORMAT, createLogger, logFormatFromArgv } from "./log.js";
import { FimApiError, FimError, FimNetworkError, FimParseError, FimValidationError, credentialsIn, echoedCredentialForms, redactUrlUserinfo, redactCredentials, redactSecrets, typedUrlCredentials, } from "@maschinenlesbar.org/fim-portal-client/internal/errors";
/** commander's exit code for a usage error (a rejected option value), kept for library rejections. */
const USAGE_EXIT_CODE = 1;
/**
 * Apply exitOverride + output redirection to every command in the tree.
 * commander does not propagate these to subcommands, so a parse error on a
 * subcommand would otherwise call process.exit() and bypass our error handling.
 */
function configureTree(command, deps, state = { errorLogged: false }) {
    command.exitOverride();
    command.configureOutput({
        writeOut: (str) => deps.io.out(str.replace(/\n$/, "")),
        writeErr: (str) => writeCommanderErr(command, deps, state, str),
    });
    for (const child of command.commands)
        configureTree(child, deps, state);
}
/** `fim-portal schemas`: the command's name with its parents'. */
function commandPath(command) {
    const names = [];
    for (let c = command; c !== null; c = c.parent)
        names.unshift(c.name());
    return names.join(" ");
}
/**
 * commander's stderr output as log records, one per line. Its `error: …` is an ERROR of
 * `cli`, with a following `(Did you mean …?)` line appended to that same record; the
 * help it shows after an error is one INFO record per non-blank line. A command group
 * run without its subcommand (or `help` with an unknown topic) makes commander show the
 * help as an error (exit 1) with no `error:` line: an ERROR record "missing command:
 * `fim-portal schemas <subcommand>`" comes first, so every failed run has one.
 */
function writeCommanderErr(command, deps, state, str) {
    const log = logOf(deps);
    const text = str.replace(/\n$/, "");
    // The blank line commander writes between an error and the help it shows after.
    if (text.trim() === "")
        return;
    if (text.startsWith("error: ")) {
        state.errorLogged = true;
        const message = text.slice("error: ".length);
        // commander quotes the rejected value raw: escape what the log would leave invisible.
        const hint = /\n(\(Did you mean [^\n]*\?\))$/.exec(message);
        log.error("cli", hint === null ? escapeTerminalText(message) : `${escapeTerminalText(message.slice(0, hint.index))} ${hint[1]}`);
        return;
    }
    if (!state.errorLogged) {
        state.errorLogged = true;
        log.error("cli", `missing command: \`${commandPath(command)} <subcommand>\``);
    }
    for (const line of text.split("\n"))
        if (line.trim() !== "")
            log.info("cli", line.trimEnd());
}
/**
 * `text` with every character a terminal acts on, or that can't be seen, written as a `\uXXXX`
 * escape: C0 (but TAB and LF, which become `\n`), DEL, C1, every format character (a zero-width
 * space, a soft hyphen, a bidi override) and a lone surrogate. commander echoes a rejected value
 * as it was typed (`argument 'a<ZWSP>b' is invalid`), so the refusal showed nothing wrong with it.
 */
function escapeTerminalText(text) {
    return text.replace(/[\u0000-\u0008\u000a-\u001f\u007f-\u009f]|\p{Cf}|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/gu, (ch) => ch === "\n" ? "\\n" : ch === "\r" ? "\\r" : `\\u${ch.charCodeAt(0).toString(16).padStart(4, "0")}`);
}
/**
 * The names (long and short) of the program's own options that require a value
 * (`--user-agent`). Only the program's: commander takes them out of argv wherever they
 * stand, before a subcommand sees the rest, so a subcommand's `--limit` never swallows
 * a `--log-format` after it.
 */
function valueOptionsOf(program) {
    const names = new Set();
    for (const option of program.options) {
        if (!option.required)
            continue;
        if (option.long !== undefined)
            names.add(option.long);
        if (option.short !== undefined)
            names.add(option.short);
    }
    return names;
}
/**
 * The options whose value is the base URL: a `user:password@host` given there without
 * its scheme is still a credential (anywhere else a bare `a:b@c` is not).
 */
const BASE_URL_FLAGS = ["--base-url"];
/** The values of the `flags` in `argv`, in both forms (`--flag value`, `--flag=value`). */
function flagValues(argv, flags) {
    const found = [];
    argv.forEach((token, i) => {
        const next = argv[i + 1];
        if (flags.includes(token) && next !== undefined)
            found.push(next);
        const eq = token.indexOf("=");
        if (eq > 0 && flags.includes(token.slice(0, eq)))
            found.push(token.slice(eq + 1));
    });
    return found;
}
/**
 * The secrets of the run in `argv`. Commander echoes rejected values in its errors
 * (`argument '<url>' is invalid`, `unknown command '<url>'`) and the help follows them:
 * whatever path a credential takes to stdout or stderr, the exact userinfo (as
 * `credentialsIn` finds it, plus its JSON-quoted form) is replaced by `***`. A URL counts
 * wherever it starts inside an argument (`urlsWithin`): padded, after a dash or inside a
 * phrase, since a text filter is sent trimmed. A pattern
 * alone can't delimit a password with spaces, quotes, `#`, `?` or `/`; the exact strings
 * can. Downloads (`outBinary`, the `-o` file) are data and pass unchanged, as does all text
 * when no argument carries credentials.
 */
export function redactionFor(argv) {
    // An `--option=value` token is echoed as its value alone.
    const values = argv.map((token) => (token.startsWith("-") && token.includes("=") ? token.slice(token.indexOf("=") + 1) : token));
    const secrets = new Set();
    // A URL given as an id is echoed percent-encoded in a request path (`alice%3Apw%40host`).
    const encoded = new Set();
    const echoed = new Set();
    const passwords = new Set();
    // A base URL typed without its scheme is read as if it had one.
    // Read as a URL however its scheme is typed: missing, special without "//", or mistyped
    // (`http//u:pw@h`, the colon left out): typedUrlCredentials.
    const baseUrls = flagValues(argv, BASE_URL_FLAGS);
    for (const found of [...values.flatMap(urlsWithin).map(credentialsIn), ...baseUrls.map(typedUrlCredentials)]) {
        for (const secret of found) {
            secrets.add(secret);
            secrets.add(JSON.stringify(secret).slice(1, -1));
            // As commander's echo of it reaches the log (escapeTerminalText).
            secrets.add(escapeTerminalText(secret));
            encoded.add(encodeURIComponent(secret));
            // What a server echoes back: the Basic value and the decoded user:password on
            // stdout and stderr, the password alone (it may well occur in the data) on stderr.
            const [basic, pair, password] = echoedCredentialForms(secret);
            if (basic !== undefined)
                echoed.add(basic);
            if (pair !== undefined)
                echoed.add(pair);
            if (password !== undefined)
                passwords.add(password);
        }
    }
    if (secrets.size === 0)
        return { out: (text) => text, err: (text) => text };
    const list = [...secrets];
    // Longest first, so a password never leaves half of the user:password around it.
    const echoedList = [...echoed].sort((a, b) => b.length - a.length);
    const passwordList = [...passwords].sort((a, b) => b.length - a.length);
    const out = (text) => {
        let result = redactUrlUserinfo(redactCredentials(text, list));
        for (const secret of encoded)
            result = result.split(`${secret}%40`).join("***%40");
        return redactSecrets(result, echoedList);
    };
    return { out, err: (text) => redactSecrets(out(text), passwordList) };
}
/** The most URLs `urlsWithin` reads inside one argument, after the one it may start with. */
const MAX_URLS_WITHIN = 64;
/** A character a URL scheme may hold after its first letter. */
const SCHEME_CHAR = /[A-Za-z0-9+.-]/;
/**
 * `value` and the rest of it from each place a URL starts inside it (`<scheme>://`, the scheme
 * starting with a letter), for `credentialsIn`, which reads a URL at the start of its input only.
 * A text filter or an id is sent trimmed and a refusal quotes the value whole, so a padded
 * `" https://user:pw@host"`, one after a dash or inside a phrase reached the request URL and the
 * messages that quote it with its password. Each `://` is found with indexOf and its scheme by
 * walking back, never by a pattern retried at every position (quadratic on a long argument); at
 * most MAX_URLS_WITHIN are read from one argument, since each is parsed whole.
 */
function urlsWithin(value) {
    const found = [value];
    for (let at = value.indexOf("://"); at !== -1 && found.length <= MAX_URLS_WITHIN; at = value.indexOf("://", at + 3)) {
        let start = at;
        while (start > 0 && SCHEME_CHAR.test(value[start - 1]))
            start--;
        while (start < at && !/[A-Za-z]/.test(value[start]))
            start++;
        if (start > 0 && start < at)
            found.push(value.slice(start));
    }
    return found;
}
/**
 * `deps` that keep the secrets of this run (`redactionFor`) out of everything they
 * print: `io.out` is redacted, and the log (`deps.log`) replaces them in each record's
 * message before formatting it, then writes to the raw `io.err`, so the frame is never
 * touched. `io.err` itself is redacted too, for anything that writes to stderr without
 * the log.
 */
export function withRedactedOutput(deps, argv) {
    const redaction = redactionFor(argv);
    const { out, err } = deps.io;
    return {
        ...deps,
        io: { ...deps.io, out: (text) => out(redaction.out(text)), err: (text) => err(redaction.err(text)) },
        log: createLogger({
            format: logFormatFromArgv(argv),
            write: err,
            redact: redaction.err,
            ...(deps.now === undefined ? {} : { now: deps.now }),
        }),
    };
}
/**
 * The log for what happens outside `run()`, in the bin shim: a stdout write error
 * (`handleOutputErrors`) and Node's process warnings (`installWarningLog`). Its format is the one argv asks for (`logFormatFromArgv`), and
 * it replaces the secrets of argv like the run's own log; it writes to the raw stderr.
 */
export function processLogger(argv) {
    return createLogger({
        format: logFormatFromArgv(argv),
        write: (line) => process.stderr.write(line + "\n"),
        redact: redactionFor(argv).err,
    });
}
/**
 * The log area of a `FimError` that is neither an API error nor a usage error: the
 * connection (`http`), a malformed answer (`api`: bad JSON, the wrong shape, an HTML page
 * answered with 200, an unknown charset — the API's answer as much as an error status
 * is), the output (`output`), else `cli`.
 */
function areaOf(err) {
    if (err instanceof FimNetworkError)
        return "http";
    if (err instanceof FimParseError)
        return "api";
    if (err instanceof OutputError)
        return "output";
    return "cli";
}
export async function run(argv, deps = defaultDeps) {
    // The log replaces the secrets of the run in every message, in either format.
    deps = withRedactedOutput(deps, argv);
    const program = buildProgram(deps);
    configureTree(program, deps);
    // For the records of a parse error: the scan of argv, now knowing which of the program's
    // options take a value, as commander reads them.
    if (deps.log !== undefined)
        deps.log.format = logFormatFromArgv(argv, valueOptionsOf(program));
    // One source for the format once commander has parsed argv: its value, not the scan
    // of argv (an option's value can look like --log-format; `--` ends the scan, not
    // commander's parse of a value). Ancestors' hooks run first, so this precedes every
    // other preAction check.
    const log = deps.log;
    program.hook("preAction", (_program, actionCommand) => {
        const format = actionCommand.optsWithGlobals().logFormat;
        if (log !== undefined)
            log.format = format ?? DEFAULT_LOG_FORMAT;
    });
    try {
        await program.parseAsync(argv, { from: "user" });
        return 0;
    }
    catch (err) {
        if (err instanceof CommanderError) {
            // Help/version requests exit 0; genuine parse errors carry their own code.
            return err.exitCode;
        }
        const log = logOf(deps);
        if (err instanceof FimApiError) {
            log.error("api", err.message);
            // Map a few notable statuses to distinct exit codes for scripting.
            if (err.status === 404)
                return 4;
            return 1;
        }
        if (err instanceof FimValidationError) {
            // An input the library refused before any request: the same usage-error
            // exit code commander uses for a rejected option value.
            log.error("cli", err.message);
            return USAGE_EXIT_CODE;
        }
        if (err instanceof FimError) {
            log.error(areaOf(err), err.message);
            return 1;
        }
        log.error("cli", `Unexpected error: ${err instanceof Error ? err.message : String(err)}`);
        return 1;
    }
}
